import java.io.*;
import java.math.*;
import java.util.*;

public class Main {

    static class Point {
        long[] c;

        Point(long... c) {
            this.c = c;
        }

        private static long sq(long x) {
            return x * x;
        }

        long lenSq() {
            return sq(c[0]) + sq(c[1]) + sq(c[2]) + sq(c[3]) + sq(c[4]);
        }

        long dot(Point other) {
            return c[0] * other.c[0] + c[1] * other.c[1] + c[2] * other.c[2] + c[3] * other.c[3] + c[4] * other.c[4];
        }

        Point sub(Point other) {
            return new Point(c[0] - other.c[0], c[1] - other.c[1], c[2] - other.c[2], c[3] - other.c[3], c[4] - other.c[4]);
        }
    }

    static boolean check(Point[] points, int n, int i) {
        Point ith = points[i];
        for (int j = 0; j < n; ++j) {
            if (j == i) continue;
            for (int k = 0; k < n; ++k) {
                if (k == i || k == j) continue;
                Point x = points[j].sub(ith);
                Point y = points[k].sub(ith);
                if (x.dot(y) > 0) return false;
            }
        }
        return true;
    }

    public static void main(String[] args) {
        InputReader reader = new InputReader(System.in);
        PrintWriter pw = new PrintWriter(System.out);

        int n = reader.nextInt();
        if (n > 11) {
            pw.printf("0\n");
            pw.flush();
            pw.close();
            return;
        }

        Point[] points = new Point[n];
        for (int i = 0; i < n; ++i) {
            points[i] = new Point(reader.nextLong(), reader.nextLong(), reader.nextLong(), reader.nextLong(), reader.nextLong());
        }

        ArrayList<Integer> ret = new ArrayList<Integer>(11);
        for (int i = 0; i < n; ++i) {
            if (check(points, n, i)) ret.add(i + 1);
        }

        pw.printf("%d\n", ret.size());
        for (Integer x : ret) {
            pw.printf("%d\n", x);
        }
        pw.flush();
        pw.close();
    }

    public static class InputReader {
        BufferedReader reader;
        StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return "0";
                    tokenizer = new StringTokenizer(line);
                } catch (IOException ioe) {
                    throw new RuntimeException(ioe);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

        public Long nextLong() {
            return Long.parseLong(next());
        }

        public BigInteger nextBigInteger() {
            return new BigInteger(next());
        }

        public String nextLine() {
            String line = "";
            try {
                while (line.equals("")) {
                    line = reader.readLine();
                }
            } catch (IOException ioe) {
                throw new RuntimeException(ioe);
            }
            return line;
        }
    }
}
